// SPDX-License-Identifier: MIT
pragma solidity ^0.8.34;

import {Ownable} from '@openzeppelin/contracts/access/Ownable.sol';
import {Math} from '@openzeppelin/contracts/utils/math/Math.sol';
import {SafeERC20} from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import {IERC20Metadata} from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {IERC20} from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import {ERC20} from '@openzeppelin/contracts/token/ERC20/ERC20.sol';
import {ERC4626} from '@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol';
import {IERC4626} from '@openzeppelin/contracts/interfaces/IERC4626.sol';
import {ERC20Permit} from '@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol';
import {ERC20Hooks} from '@1inch/token-hooks/contracts/ERC20Hooks.sol';
import {IERC20Permit} from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol';

import {ITransferValidator} from 'contracts/interfaces/callbacks/ITransferValidator.sol';
import {IAmmalgamERC20} from 'contracts/interfaces/tokens/IAmmalgamERC20.sol';
import {
    FIRST_DEBT_TOKEN,
    DEPOSIT_L,
    DEPOSIT_X,
    DEPOSIT_Y,
    BORROW_X,
    BORROW_Y
} from 'contracts/interfaces/tokens/ITokenController.sol';
import {IHookRegistry} from 'contracts/interfaces/tokens/IHookRegistry.sol';
import {ZERO_ADDRESS} from 'contracts/libraries/constants.sol';
import {Validation} from 'contracts/libraries/Validation.sol';

struct ERC20BaseConfig {
    address pair;
    IHookRegistry hookRegistry;
    string name;
    string symbol;
    uint256 tokenType;
}

abstract contract ERC20Base is ERC20Hooks, Ownable, ERC20Permit, IAmmalgamERC20 {
    ITransferValidator public immutable pair;
    IHookRegistry private immutable hookRegistry;

    uint256 public immutable tokenType;

    error HookIsNotAllowed();

    /**
     * @notice This boolean is reserved for moving collateral to liquidators. And we reuse it
     * to transfer debt from the pair to a borrower. Since the borrower might already be in trouble
     * if this is called during a liquidation, we do not call `validateOnUpdate` to avoid failing
     * on the loan to value check. This also means that saturation is not updated for this penalty
     * owed. we think this is an acceptable discrepancy since it is only the penalty for over
     * saturation that is not being included in the saturation update, which should be a negligible
     * amount with respect to the total debt. Once a position is updated either by the users
     * actions, or by a saturation liquidation reset, this penalty will be adjusted to the correct
     * value in the Saturation State.
     */
    // slither-disable-next-line uninitialized-state default false is correct initial state
    bool transient ownerTransferSkipValidation;

    constructor(
        ERC20BaseConfig memory config
    )
        ERC20(config.name, config.symbol)
        ERC20Hooks(10, 500_000) // hooksLimit, hookCallGasLimit
        ERC20Permit(config.name)
        Ownable(config.pair)
    {
        pair = ITransferValidator(config.pair);
        tokenType = config.tokenType;
        hookRegistry = config.hookRegistry;
    }

    // Override the nonces function explicitly for ERC20Permit
    function nonces(
        address owner
    ) public view virtual override(ERC20Permit, IERC20Permit) returns (uint256) {
        return super.nonces(owner);
    }

    function ownerMint(address sender, address to, uint256 assets, uint256 shares) public virtual onlyOwner {}

    function ownerTransfer(address from, address to, uint256 amount) public virtual onlyOwner {
        ownerTransferSkipValidation = true;
        // slither-disable-next-line reentrancy-no-eth,reentrancy-benign,reentrancy-events _transfer is in ERC20 and does not make other calls
        _transfer(from, to, amount);
        ownerTransferSkipValidation = false;
    }

    function balanceOf(
        address account
    ) public view virtual override(ERC20, ERC20Hooks, IERC20) returns (uint256) {
        return super.balanceOf(account);
    }

    function decimals() public view virtual override(ERC20, IERC20Metadata) returns (uint8) {
        return super.decimals();
    }

    /**
     * @notice Updates the pair state based on the transfer.
     * @dev Triggers pair state updates for DEPOSIT_L and debt token transfers
     * to avoid potential L token accumulation in the pair during burn operations.
     * @param from The address of the sender.
     * @param to The address of the recipient.
     * @param amount The amount of tokens transferred.
     */
    function _update(address from, address to, uint256 amount) internal virtual override(ERC20, ERC20Hooks) {
        super._update(from, to, amount);
        if (amount == 0) return;
        if (from != ZERO_ADDRESS && to != ZERO_ADDRESS) {
            if (!ownerTransferSkipValidation) {
                (address validate, address update, bool alwaysUpdate) = (tokenType < FIRST_DEBT_TOKEN)
                    ? (from, to, tokenType == DEPOSIT_L) // For non-debt tokens
                    : (to, from, true); // For debt tokens
                pair.validateOnUpdate(validate, update, alwaysUpdate);
            } else {
                // handle the case where ownerTransfer gets called directly from liquidationTransfer.
                if (
                    (tokenType == DEPOSIT_X && pair.tokens(BORROW_X).balanceOf(to) > 0)
                        || (tokenType == DEPOSIT_Y && pair.tokens(BORROW_Y).balanceOf(to) > 0)
                ) {
                    revert Validation.AmmalgamCannotBorrowAgainstSameCollateral();
                }
            }
        }
    }

    function addHook(
        address hook
    ) public override {
        if (hookRegistry.isHookAllowed(hook)) {
            super._addHook(msg.sender, hook);
        } else {
            revert HookIsNotAllowed();
        }
    }
}

