    function getMinAndMaxOfThree(int16 a, int16 b, int16 c) private pure returns (int16 min, int16 max) {
        (min, max) = c < b ? (c, b) : (b, c);
        if (a < min) {
            min = a;
        } else if (max < a) {
            max = a;
        }
    }

