// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.34;

import {IERC20} from '@openzeppelin/contracts/interfaces/IERC20.sol';
import {IBeacon} from '@openzeppelin/contracts/proxy/beacon/IBeacon.sol';
import {Address} from '@openzeppelin/contracts/utils/Address.sol';
import {Proxy} from '@openzeppelin/contracts/proxy/Proxy.sol';
import {BeaconProxy} from '@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol';
import {ERC1967Utils} from '@openzeppelin/contracts/proxy/ERC1967/ERC1967Utils.sol';

import {AmmalgamPair} from 'contracts/AmmalgamPair.sol';
import {IAmmalgamFactory} from 'contracts/interfaces/factories/IAmmalgamFactory.sol';
import {IFactoryCallback} from 'contracts/interfaces/factories/IFactoryCallback.sol';
import {IAmmalgamERC20} from 'contracts/interfaces/tokens/IAmmalgamERC20.sol';
import {ITokenFactory} from 'contracts/interfaces/factories/ITokenFactory.sol';
import {IHookRegistry} from 'contracts/interfaces/tokens/IHookRegistry.sol';
import {ISaturationAndGeometricTWAPState} from 'contracts/interfaces/ISaturationAndGeometricTWAPState.sol';
import {
    ITokenController,
    DEPOSIT_L,
    DEPOSIT_X,
    DEPOSIT_Y,
    BORROW_L,
    BORROW_X,
    BORROW_Y
} from 'contracts/interfaces/tokens/ITokenController.sol';
import {ZERO_ADDRESS} from 'contracts/libraries/constants.sol';
import {TokenSymbol} from 'contracts/libraries/TokenSymbol.sol';
import {PairBeaconProxy} from 'contracts/proxy/PairBeaconProxy.sol';
import {ERC20BaseConfig} from 'contracts/tokens/ERC20Base.sol';

contract AmmalgamFactory is IAmmalgamFactory {
    IBeacon public immutable override pairBeacon;
    IHookRegistry public immutable hookRegistry;
    ITokenFactory private immutable liquidityTokenFactory;
    ITokenFactory private immutable depositTokenFactory;
    ITokenFactory private immutable debtTokenFactory;
    ITokenFactory private immutable liquidityDebtTokenFactory;
    ISaturationAndGeometricTWAPState public immutable saturationAndGeometricTWAPState;

    IFactoryCallback.TokenFactoryConfig private config;

    address public feeTo;
    address public feeToSetter;

    mapping(address => mapping(address => address)) public getPair;
    address[] public allPairs;

    event NewFeeTo(address indexed feeTo);
    event NewFeeToSetter(address indexed feeToSetter);

    error IdenticalAddresses();
    error ZeroAddress();
    error FeeToIsZeroAddress();
    error FeeToSetterIsZeroAddress();
    error PairExists();
    error BytecodeLengthZero();
    error NewSatProxyIsZeroAddress();
    error FailedOnDeploy();
    error Forbidden();
    error NewTokensFailed();
    error ERC20TokenFactoryFailed();

    modifier onlyFeeToSetter() {
        if (msg.sender != feeToSetter) {
            revert Forbidden();
        }
        _;
    }

    constructor(
        address _feeToSetter,
        IBeacon _pairBeacon,
        IHookRegistry _hookRegistry,
        ISaturationAndGeometricTWAPState _saturationAndGeometricTWAPState,
        ITokenFactory _liquidityTokenFactory,
        ITokenFactory _depositTokenFactory,
        ITokenFactory _borrowTokenFactory,
        ITokenFactory _liquidityDebtTokenFactory
    ) {
        if (_feeToSetter == ZERO_ADDRESS) {
            revert FeeToSetterIsZeroAddress();
        }
        if (
            address(_pairBeacon) == ZERO_ADDRESS || address(_hookRegistry) == ZERO_ADDRESS
                || address(_saturationAndGeometricTWAPState) == ZERO_ADDRESS
                || address(_liquidityTokenFactory) == ZERO_ADDRESS || address(_depositTokenFactory) == ZERO_ADDRESS
                || address(_borrowTokenFactory) == ZERO_ADDRESS || address(_liquidityDebtTokenFactory) == ZERO_ADDRESS
        ) {
            revert ZeroAddress();
        }

        feeToSetter = _feeToSetter;
        liquidityTokenFactory = _liquidityTokenFactory;
        depositTokenFactory = _depositTokenFactory;
        debtTokenFactory = _borrowTokenFactory;
        liquidityDebtTokenFactory = _liquidityDebtTokenFactory;
        pairBeacon = _pairBeacon;
        hookRegistry = _hookRegistry;
        saturationAndGeometricTWAPState = _saturationAndGeometricTWAPState;
    }

    function allPairsLength() external view returns (uint256) {
        return allPairs.length;
    }

    function createPair(address tokenA, address tokenB) external returns (address pair) {
        if (tokenA == tokenB) {
            revert IdenticalAddresses();
        }
        (address tokenX, address tokenY) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);

        if (tokenX == ZERO_ADDRESS) {
            revert ZeroAddress();
        }

        if (getPair[tokenX][tokenY] != ZERO_ADDRESS) {
            // single check is sufficient
            revert PairExists();
        }

        bytes32 salt = keccak256(abi.encodePacked(tokenX, tokenY));

        config = IFactoryCallback.TokenFactoryConfig({tokenX: tokenX, tokenY: tokenY});

        pair = createPairFromSalt(salt);

        if (pair == ZERO_ADDRESS) {
            revert FailedOnDeploy();
        }

        delete config;
        getPair[tokenX][tokenY] = pair;
        getPair[tokenY][tokenX] = pair; // populate mapping in the reverse direction
        allPairs.push(pair);
        emit PairCreated(tokenX, tokenY, pair, allPairs.length);
    }

    function getConfig() private view returns (IFactoryCallback.TokenFactoryConfig memory) {
        if (config.tokenX == ZERO_ADDRESS || config.tokenY == ZERO_ADDRESS) {
            revert ZeroAddress();
        }
        return config;
    }

    function generateTokensWithinFactory() external returns (IERC20, IERC20, IAmmalgamERC20[6] memory) {
        IFactoryCallback.TokenFactoryConfig memory _config = getConfig();
        // msg.sender == pair
        // address(this) == factory
        IAmmalgamERC20[6] memory tokens = createAllTokens(msg.sender, _config.tokenX, _config.tokenY);

        // slither-disable-next-line reentrancy-events
        emit LendingTokensCreated(
            msg.sender,
            address(tokens[0]),
            address(tokens[1]),
            address(tokens[2]),
            address(tokens[3]),
            address(tokens[4]),
            address(tokens[5])
        );

        return (IERC20(_config.tokenX), IERC20(_config.tokenY), tokens);
    }

    function createAllTokens(
        address pair,
        address tokenX,
        address tokenY
    ) private returns (IAmmalgamERC20[6] memory tokens) {
        IHookRegistry _hookRegistry = hookRegistry;
        string memory symbolX = TokenSymbol.uniSymbol(tokenX);
        string memory symbolY = TokenSymbol.uniSymbol(tokenY);
        string memory symbolXAndY = string.concat(symbolX, '-', symbolY);

        tokens[DEPOSIT_L] = createToken(
            address(liquidityTokenFactory),
            ZERO_ADDRESS,
            ERC20BaseConfig(
                pair,
                _hookRegistry,
                string.concat('Ammalgam Liquidity ', symbolXAndY),
                string.concat('AMG-', symbolXAndY),
                DEPOSIT_L
            )
        );
        tokens[DEPOSIT_X] = createToken(
            address(depositTokenFactory),
            tokenX,
            ERC20BaseConfig(
                pair,
                _hookRegistry,
                string.concat('Ammalgam Deposited ', symbolX),
                string.concat('AMG-', symbolX),
                DEPOSIT_X
            )
        );
        tokens[DEPOSIT_Y] = createToken(
            address(depositTokenFactory),
            tokenY,
            ERC20BaseConfig(
                pair,
                _hookRegistry,
                string.concat('Ammalgam Deposited ', symbolY),
                string.concat('AMG-', symbolY),
                DEPOSIT_Y
            )
        );
        tokens[BORROW_X] = createToken(
            address(debtTokenFactory),
            tokenX,
            ERC20BaseConfig(
                pair,
                _hookRegistry,
                string.concat('Ammalgam Borrowed ', symbolX),
                string.concat('AMGB-', symbolX),
                BORROW_X
            )
        );
        tokens[BORROW_Y] = createToken(
            address(debtTokenFactory),
            tokenY,
            ERC20BaseConfig(
                pair,
                _hookRegistry,
                string.concat('Ammalgam Borrowed ', symbolY),
                string.concat('AMGB-', symbolY),
                BORROW_Y
            )
        );
        tokens[BORROW_L] = createToken(
            address(liquidityDebtTokenFactory),
            ZERO_ADDRESS,
            ERC20BaseConfig(
                pair,
                _hookRegistry,
                string.concat('Ammalgam Borrowed Liquidity ', symbolXAndY),
                string.concat('AMGB-', symbolXAndY),
                BORROW_L
            )
        );
    }

    function setFeeTo(
        address newFeeTo
    ) external onlyFeeToSetter {
        if (newFeeTo == ZERO_ADDRESS) {
            revert FeeToIsZeroAddress();
        }
        feeTo = newFeeTo;
        emit NewFeeTo(newFeeTo);
    }

    function setFeeToSetter(
        address newFeeToSetter
    ) external onlyFeeToSetter {
        if (newFeeToSetter == ZERO_ADDRESS) {
            revert FeeToSetterIsZeroAddress();
        }
        feeToSetter = newFeeToSetter;
        emit NewFeeToSetter(newFeeToSetter);
    }

    function createPairFromSalt(
        bytes32 salt
    ) private returns (address pair) {
        // slither-disable-next-line too-many-digits
        bytes memory bytecode = type(PairBeaconProxy).creationCode;
        // slither-disable-start assembly
        assembly {
            pair := create2(0, add(bytecode, 32), mload(bytecode), salt)
        }
        // slither-disable-end assembly
    }

    function createToken(
        address tokenFactory,
        address asset,
        ERC20BaseConfig memory _config
    ) private returns (IAmmalgamERC20) {
        // The factory called here is an immutable address stored at
        // construction. A trusted and properly verified deployment of this
        // contract ensures these calls are safe.
        // slither-disable-next-line low-level-calls,controlled-delegatecall
        (bool success, bytes memory data) =
            tokenFactory.delegatecall(abi.encodeWithSelector(ITokenFactory.createToken.selector, _config, asset));
        if (!success) {
            revert ERC20TokenFactoryFailed();
        }
        return abi.decode(data, (IAmmalgamERC20));
    }
}

