        (minTick, maxTick) = getMinAndMaxOfFour(longTermTick, midTermTick, blockTick, currentTick);

        // `minTick` & `maxTick` bound check to be within the range of `MIN_TICK` and `MAX_TICK`.
        unchecked {
            // 0 <= delta <= MAX_TICK-MIN_TICK
