        uint24 midTermIntervalConfig = self.midTermIntervalConfig; // gas savings
        int56 currentCumulativeSum = getMidTermAtLastIndex(self, self.midTermIndex);

        if (tickAvailable && timeElapsedSinceUpdate >= midTermIntervalConfig) {
